return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=2; plural=(n != 1 && n != 2 && n != 3 && (n%10 == 4 || n%10 == 6 || n%10 == 9));','language'=>'tl','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-02T10:29:44+00:00','po-revision-date'=>'2026-10-02T10:29:44+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'Magbenta ng Zinn Digital® hosting mula sa sarili mong WordPress site — WordPress, WooCommerce, agency, reseller, cloud, at VPS hosting. Maghanap at mag-alok ng mga domain mula sa iyong reseller account, direktang i-sign in ang iyong mga kliyente sa kanilang hosting panel, at awtomatikong mag-provision ng hosting kapag nabayaran na ang isang order sa WooCommerce.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'Sumagot ang hosting platform nang may status %d.','Find your domain name'=>'Hanapin ang iyong domain name','Search'=>'Maghanap','No extensions were checked for that name.'=>'Walang mga extension na sinuri para sa pangalang iyon.','Domain search is unavailable on this site at the moment.'=>'Hindi available ang paghahanap ng domain sa site na ito sa kasalukuyan.','We could not reach the domain registry just now. Please try again in a moment.'=>'Hindi namin makontak ang domain registry ngayon lang. Pakisubukan ulit pagkalipas ng ilang sandali.','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'Nawawala o hindi na valid ang API key. Tingnan ito sa ilalim ng Zinn Digital® → Reseller Toolkit.','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'Walang pahintulot na sites.view ang API key na ito, na kailangan ng paghahanap ng domain. Idagdag ito sa key sa iyong reseller panel, o i-clear ang key rito para bumalik sa pampublikong paghahanap.','Only administrators see this:'=>'Mga administrator lang ang nakakakita nito:','We could not check this one — try again'=>'Hindi namin masuri ito — subukan mo ulit','Already registered'=>'Nakarehistro na','Available — ask us for a price'=>'Available — itanong sa amin ang presyo','Available — %1$s %2$s for the first year'=>'Available — %1$s %2$s para sa unang taon','Register it'=>'Irehistro ito','Manage my hosting'=>'Pamahalaan ang aking hosting','Please sign in first.'=>'Mangyaring mag-sign in muna.','This account is not linked to a hosting service yet.'=>'Hindi pa nakakonekta ang account na ito sa isang serbisyo sa pag-host.','The hosting platform did not return a sign-in link.'=>'Hindi nagbalik ng sign-in link ang hosting platform.','Reseller Toolkit'=>'Toolkit ng Reseller','Account'=>'Account','Features'=>'Mga Feature','Styling'=>'Pag-istilo','AI agents (MCP)'=>'Mga AI agent (MCP)','Allow AI agents (MCP)'=>'Payagan ang mga AI agent (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'Naka-off: ang mga tool sa ibaba at ang kanilang mga REST route ay hindi nakarehistro.','Your Zinn Digital® reseller account'=>'Ang iyong Zinn Digital® reseller account','Create a reseller API key in your Zinn® dashboard under Developer → API keys, and paste it here.'=>'Gumawa ng reseller API key sa iyong Zinn® dashboard sa ilalim ng Developer → API keys, at i-paste ito rito.','Reseller API key'=>'API key ng reseller','Held on this site only, and never included in an export or a diagnostics report.'=>'Nakatago sa site na ito lamang, at hindi kailanman isinasama sa isang pag-export o ulat ng diagnostics.','Plan to provision'=>'Plan na ipo-provision','The plan code new customers are put on. Leave blank to be asked each time.'=>'Ang plan code kung saan ilalagay ang mga bagong customer. Iwanang blangko upang tanungin ka sa bawat pagkakataon.','API address'=>'Address ng API','Leave this alone unless Zinn® support has asked you to change it.'=>'Hayaan mo lang ito maliban kung hiniling sa iyo ng suporta ng Zinn® na baguhin ito.','Control-panel address'=>'Address ng control panel','Where the “My hosting” link sends your customers.'=>'Kung saan dinadala ng link na “Aking hosting” ang iyong mga kostumer.','Domain search'=>'Paghahanap ng domain','Provide the [zinn_domain_search] shortcode'=>'Ibigay ang [zinn_domain_search] shortcode','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'Ilagay ang shortcode sa anumang pahina upang payagan ang mga bisita na suriin ang isang domain at bilhin ito sa pamamagitan mo.','Panel link'=>'Link ng panel','Show a “My hosting” link to signed-in customers'=>'Magpakita ng link na "Aking hosting" sa mga naka-sign in na customer','WooCommerce provisioning'=>'Pag-provision ng WooCommerce','Provision hosting automatically when a WooCommerce order completes'=>'Awtomatikong maglaan ng hosting kapag nakumpleto ang isang order sa WooCommerce','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'Magkakabisa lamang sa mga order na naglalaman ng produkto na iminapa mo sa isang Zinn® plan.','Domain search appearance'=>'Hitsura ng paghahanap ng domain','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'Nagre-render ang widget na ito sa loob ng sarili mong tema. Pumili ng preset, o magtakda ng sarili mong mga kulay — alinman ang piliin, walang idinadagdag sa iyong mga pahina na makikita ng bisita na amin.','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'Nakalista ang bawat class na ginagamit ng widget sa readme ng plugin, para ma-override ng developer ang anumang hindi sakop ng preset.','Follow my theme'=>'Sundin ang aking tema','Soft'=>'Malambot','High contrast'=>'Mataas na contrast','Compact'=>'Compact','Buy-link colour'=>'Kulay ng link ng pagbili','“Available” colour'=>'Kulay ng "Available"','“Could not check” colour'=>'Kulay ng "Hindi masuri"','Error colour'=>'Kulay ng error','Corner rounding'=>'Pag-round ng kanto','Space inside each row'=>'Puwang sa loob ng bawat hilera','Text size'=>'Laki ng teksto','Domain-name weight'=>'Timbang ng domain name','No reseller API key yet.'=>'Wala pang reseller API key.','Domain search already works without one, at the public prices. The panel link and WooCommerce provisioning need a key: create one in your Zinn® dashboard under Developer → API keys.'=>'Gumagana na ang paghahanap ng domain nang wala nito, sa mga pampublikong presyo. Ang link ng panel at ang provisioning ng WooCommerce ay nangangailangan ng key: gumawa ng isa sa iyong Zinn® dashboard sa ilalim ng Developer → API keys.','Open my Zinn® dashboard'=>'Buksan ang aking dashboard sa Zinn®','A key is set, but nothing is switched on.'=>'May nakatakdang key, ngunit walang naka-on.','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'Wala sa tatlong feature ang pinagana, kaya walang ginagawa ang plugin na ito sa iyong site. I-on ang kailangan mo sa ilalim ng Mga Feature.','Open Features'=>'Buksan ang Mga Feature','Ready — %d feature switched on.'=>'Handa na — %d tampok ang binuksan.' . "\0" . 'Handa na — %d (na) feature ang naka-on.','Selling from'=>'Nagbebenta mula sa','Settings'=>'Mga Setting','No API key yet, so nothing is connected.'=>'Wala pang API key, kaya walang nakakonekta.','Not connected: %s'=>'Hindi nakakonekta: %s','Connected. Your reseller programme is %s.'=>'Konektado na. Ang iyong reseller program ay %s.','No Zinn® API key is configured, so nothing was provisioned.'=>'Walang naka-configure na Zinn® API key, kaya walang na-provision.','This order did not include a domain name, so there was nothing to provision.'=>'Hindi kasama sa order na ito ang domain name, kaya walang maia-provision.','The hosting platform did not return a site.'=>'Hindi nagbalik ng site ang hosting platform.','Zinn® hosting provisioned for %1$s (service %2$s).'=>'Na-provision ang Zinn® hosting para sa %1$s (serbisyo %2$s).','The hosting platform did not return a client account.'=>'Hindi nagbalik ng account ng kliyente ang hosting platform.','Zinn® hosting was NOT provisioned: %s'=>'HINDI na-provision ang Zinn® hosting: %s','Zinn® product line'=>'Linya ng produkto ng Zinn®','The Zinn® product line to provision when this product is bought. Leave blank to use the default from the plugin settings.'=>'Ang linya ng produkto ng Zinn® na ipagkakaloob kapag binili ang produktong ito. Iwanang blangko upang gamitin ang default mula sa mga setting ng plugin.','Zinn® hosting'=>'Zinn® hosting','Service id'=>'ID ng serbisyo','Nothing provisioned for this order.'=>'Walang na-provision para sa order na ito.','Stored. Type a new value to replace it.'=>'Nai-save na. Mag-type ng bagong value para palitan ito.','Filter this list…'=>'I-filter ang listahang ito…','Filter this list'=>'I-filter ang listahang ito','Nothing matches that filter.'=>'Walang tumutugma sa filter na iyon.','Add a row'=>'Magdagdag ng row','Remove this row'=>'Alisin ang row na ito','Remove'=>'Alisin','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pangkalahatang-ideya','Overview'=>'Pangkalahatang-ideya','Copied'=>'Nakopya na','Every Zinn® plugin on this site, and whether it is working.'=>'Bawat plugin ng Zinn® sa site na ito, at kung ito ay gumagana.','No connection is needed for this plugin.'=>'Walang koneksyon na kailangan para sa plugin na ito.','Open settings'=>'Buksan ang mga setting','You do not have permission to change these settings.'=>'Wala kang pahintulot na baguhin ang mga setting na ito.','Settings sections'=>'Mga seksyon ng setting','Support'=>'Suporta','Save changes'=>'I-save ang mga pagbabago','Tools'=>'Mga Tool','Export settings'=>'I-export ang mga setting','Reset to defaults'=>'I-reset sa mga default','This puts every setting on this plugin back to its default. Continue?'=>'Ibablik nito ang bawat setting sa plugin na ito sa default nito. Magpatuloy?','Diagnostics for support'=>'Mga diagnostic para sa suporta','Import a settings file'=>'Mag-import ng file ng mga setting','Import'=>'Mag-import','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Ang mga na-export na file ay hindi kailanman naglalaman ng mga password, token o mga API key — kakailanganin mong ilagay muli ang mga iyon sa bagong site.','Settings saved.'=>'Nai-save ang mga setting.','Every setting on this plugin is back to its default.'=>'Naibalik na sa default ang bawat setting sa plugin na ito.','Done.'=>'Tapos na.','That action is not available.'=>'Hindi available ang gawaing iyon.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Hindi mabasa ang file na iyon. Pumili ng settings file na na-export mula sa isang Zinn® plugin.','That file is too large to be a settings export.'=>'Napakalaki ng file na iyon para maging pag-export ng mga setting.','That file is not a Zinn® settings export.'=>'Ang file na iyon ay hindi isang pag-export ng mga setting ng Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Na-export ang file na iyon mula sa ibang plugin (%s), kaya ang pag-import nito rito ay magse-save ng mga setting na hindi naiintindihan ng plugin na ito.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d setting ang na-import. Hindi kailanman kasama sa export ang mga password at API key, kaya ilagay mo itong muli.' . "\0" . '%d setting ang na-import. Ang mga password at API key ay hindi kailanman kasama sa pag-export, kaya ilagay mo ulit ang mga ito.','Connected'=>'Konektado','Connecting…'=>'Kumokonekta…','Connected, but something needs attention'=>'Konektado, ngunit may kailangang bigyang-pansin','Not connected'=>'Hindi nakakonekta','Running on your own account'=>'Tumatakbo sa sarili mong account','We could not check this'=>'Hindi namin ito masuri','This plugin did not say why. Send a diagnostics report and we will look.'=>'Hindi sinabi ng plugin na ito kung bakit. Magpadala ng ulat ng diagnostics at titingnan namin.','Connection status'=>'Katayuan ng koneksyon','Last checked %s ago.'=>'Huling sinuri %s ang nakalipas.','(opens in a new tab)'=>'(bubukas sa bagong tab)','Send this to Zinn® support'=>'Ipadala ito sa suporta ng Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Ito mismo ang ipapadala — wala nang iba, at walang nakatago. Wala rito ang iyong mga password, token, at API key.','The diagnostics report that will be sent'=>'Ang ulat sa diagnostics na ipapadala','Copy to clipboard'=>'Kopyahin sa clipboard','Send this report to Zinn® support'=>'Ipadala ang ulat na ito sa suporta ng Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Magbubukas kami ng support ticket para sa iyo at sasagot sa pamamagitan ng email. Kung mas gusto mong huwag itong ipadala, kopyahin ito sa itaas at i-paste ito sa ticket nang ikaw mismo.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Hindi namin maabot ang Zinn Digital® mula sa server na ito (%s). Kopyahin ang ulat sa itaas at magbukas na lang ng ticket — walang mali sa iyong mga setting.','Sent. Zinn® support has your report and will reply by email.'=>'Naipadala na. Natanggap na ng suporta ng Zinn® ang iyong ulat at sasagot sa pamamagitan ng email.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Naipadala na. Natanggap na ng suporta ng Zinn® ang iyong ulat — sanggunian %s — at sasagot sa pamamagitan ng email.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Nagpadala ka ng ilang ulat sa maikling panahon. Maghintay ng ilang minuto at subukang muli — nakarating naman ang mga nauna.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Hindi matanggap ng Zinn Digital® ang ulat ngayon — sa amin ang problema, hindi sa iyo. Subukang muli mamaya, o kopyahin ang ulat sa itaas sa isang ticket.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Tinanggihan ang ulat (HTTP %d). Kopyahin ito sa itaas at magbukas ng ticket, na binabanggit ang numerong iyon.','%s — guides and services'=>'%s — mga gabay at serbisyo','User guides'=>'Mga gabay ng user','Read the %s user guide'=>'Basahin ang gabay sa gumagamit ng %s','Hide this'=>'Itago ito','Zinn® hosting for WordPress'=>'Zinn® hosting para sa WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, mga pang-araw-araw na backup, libreng paglipat, at isang control panel na binuo para sa mga taong nagpapatakbo ng higit sa isang site.','The Zinn® marketplace'=>'Ang marketplace ng Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Bumili at magbenta ng mga naitatag nang site, domain, at placement ng link, kung saan ligtas na hawak ang pera hanggang sa maging masaya ang magkabilang panig.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — kumuha ng mga taong ito ang ikinabubuhay','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Ang aming pambuong-mundong freelance marketplace: mag-browse sa mahigit 10,000 handang serbisyo mula sa mga manunulat, designer, developer, at SEO specialist, o mag-post ng proyekto at hayaan silang mag-bid.','Style preset'=>'Preset ng estilo','A starting point. Anything below overrides it.'=>'Isang panimulang punto. Anumang nasa ibaba ay magpapawalang-bisa rito.','Use my own colours and sizes'=>'Gamitin ang sarili kong mga kulay at laki','Leave this off and the preset is used exactly as it is.'=>'Iwanan itong naka-off at gagamitin ang preset nang eksakto kung ano ito.','See the Zinn Digital® release notes.'=>'Tingnan ang mga tala sa paglabas ng Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Hindi nagbigay ang serbisyo sa pag-update ng Zinn® ng link sa pag-download para sa pag-update na ito. Suriin kung naaabot ng site na ito ang platform ng Zinn®, pagkatapos ay subukang muli.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Hindi ma-download ang update mula sa serbisyo ng pag-update ng Zinn® (%s). Subukan ulit pagkalipas ng ilang minuto.','The downloaded update failed its integrity check and was not installed.'=>'Bumagsak ang na-download na update sa pagsusuri sa integridad nito at hindi na-install.','The action could not be completed. Try again, and if it keeps failing, contact the site administrator.'=>'Hindi makumpleto ang aksyon. Subukan muli, at kung patuloy itong mabigo, makipag-ugnayan sa administrator ng site.','Connect an AI app'=>'Magkonekta ng isang AI app','This connection request has expired. Go back to the app and start connecting again.'=>'Nag-expire na ang kahilingang ito sa koneksyon. Bumalik sa app at magsimulang kumonekta muli.','%1$s is asking to use %2$s on this site as %3$s. It can do only what your WordPress account is allowed to do, and you can disconnect it at any time from the AI agents (MCP) settings.'=>'Humihiling ang %1$s na gamitin ang %2$s sa site na ito bilang %3$s. Magagawa lamang nito kung ano ang pinapayagang gawin ng iyong WordPress account, at maaari mo itong idiskonekta anumang oras mula sa mga setting ng AI agents (MCP).','%1$s identified itself from %2$s.'=>'Ipinakilala ng %1$s ang sarili nito mula sa %2$s.','%1$s registered itself automatically. Only continue if you started this from %2$s.'=>'Awtomatikong nagparehistro ang %1$s. Magpatuloy lamang kung sinimulan mo ito mula sa %2$s.','Your account cannot use these tools on this site. Ask an administrator.'=>'Hindi maaaring gamitin ng iyong account ang mga tool na ito sa site na ito. Magtanong sa isang administrator.','After you answer you will go back to %s.'=>'Pagkatapos mong sumagot babalik ka sa %s.','Allow %s'=>'Payagan ang %s','Do not allow'=>'Huwag payagan','A required value is missing or has the wrong form. Check the ability\'s input schema.'=>'May nawawalang kinakailangang value o mali ang anyo nito. Suriin ang input schema ng kakayahan.','The site refused the request.'=>'Tinanggihan ng site ang kahilingan.','Let AI assistants such as Claude, Cursor or VS Code work on this site for you through MCP (Model Context Protocol). They sign in as a WordPress user (Claude and ChatGPT by approving them here, others with an application password) and can do only what that user is allowed to do.'=>'Pahintulutan ang mga AI assistant tulad ng Claude, Cursor, o VS Code na magtrabaho sa site na ito para sa iyo sa pamamagitan ng MCP (Model Context Protocol). Nagsa-sign in sila bilang isang WordPress user (ang Claude at ChatGPT sa pamamagitan ng pag-apruba sa kanila rito, ang iba ay gamit ang application password) at magagawa lamang kung ano ang pinapayagang gawin ng user na iyon.','AI agents need WordPress 6.9 or later. Update WordPress to use them.'=>'Kailangan ng mga AI agent ang WordPress 6.9 o mas bago. I-update ang WordPress para magamit ang mga ito.','Connection address (MCP endpoint)'=>'Address ng koneksyon (MCP endpoint)','Claude and ChatGPT: sign in instead'=>'Claude at ChatGPT: mag-sign in na lang','Add the connection address as a custom connector in Claude, or as an app in ChatGPT developer mode. They open this site so you can approve them; no password to copy.'=>'Idagdag ang address ng koneksyon bilang isang custom na connector sa Claude, o bilang isang app sa developer mode ng ChatGPT. Binubuksan nila ang site na ito para maaprubahan mo ang mga ito; walang password na kokopyahin.','AI apps connected to your account:'=>'Mga AI app na nakakonekta sa iyong account:','Disconnect'=>'Idiskonekta','Other AI apps: an application password'=>'Iba pang mga AI app: isang password ng application','Create an application password for your user'=>'Gumawa ng password ng application para sa iyong user','Add this to your AI app’s MCP settings, with your username and that password:'=>'Idagdag ito sa mga setting ng MCP ng iyong AI app, kasama ang iyong username at ang password na iyon:','VS Code: put the same entry under "servers" in .vscode/mcp.json, not under "mcpServers".'=>'VS Code: ilagay ang parehong entry sa ilalim ng "servers" sa .vscode/mcp.json, hindi sa ilalim ng "mcpServers".','Tools an AI agent can use here (%d):'=>'Mga tool na maaaring gamitin ng isang AI agent dito (%d):','User guide: AI agents and MCP'=>'Gabay ng gumagamit: Mga AI agent at MCP','Developer docs: abilities, REST and MCP'=>'Mga doc ng developer: mga kakayahan, REST at MCP','Manage your hosting clients, their plans and their sites on Zinn Digital® from this site.'=>'Pamahalaan ang iyong mga kliyente sa pag-host, ang kanilang mga plano at kanilang mga site sa Zinn Digital® mula sa site na ito.','Your clients, their plans and their sites, through your Zinn Digital® reseller account.'=>'Ang iyong mga kliyente, ang kanilang mga plano at kanilang mga site, sa pamamagitan ng iyong Zinn Digital® reseller account.','Read your reseller account'=>'Basahin ang iyong reseller account','Returns your reseller account in one read: brand, plans, clients and services counts, and what is set up.'=>'Ibinabalik ang iyong reseller account sa isang pagbasa: brand, mga plano, bilang ng mga kliyente at serbisyo, at kung ano ang naka-set up.','List your clients'=>'Ilista ang iyong mga kliyente','Lists your client accounts, a page at a time (cursor, limit).'=>'Inililista ang iyong mga client account, nang paisa-isang pahina (cursor, limit).','Create a client'=>'Gumawa ng client','Creates a client account under yours (name; default_currency, a three-letter code). Put them on a plan before their first site.'=>'Gumagawa ng client account sa ilalim ng account mo (name; default_currency, isang tatlong-titik na code). Ilagay sila sa isang plano bago ang kanilang unang site.','Read a client\'s plan'=>'Basahin ang plano ng isang kliyente','Returns which plan a client is on and what it costs you (client_id).'=>'Ibinabalik kung aling plano naroroon ang isang kliyente at kung magkano ang gastos nito sa iyo (client_id).','Put a client on a plan'=>'Maglagay ng kliyente sa isang plano','Puts a client on one of your plans (client_id, plan_code; interval: month or year). Do this before their first site.'=>'Inilalagay ang isang kliyente sa isa sa iyong mga plano (client_id, plan_code; interval: month o year). Gawin ito bago ang kanilang unang site.','List the plans you can sell'=>'Ilista ang mga planong maaari mong ibenta','Lists the hosting plans and their prices (product_line and currency narrow it).'=>'Inililista ang mga plano sa pag-host at ang kanilang mga presyo (nililimitahan ito ng product_line at currency).','List your clients\' sites'=>'Ilista ang mga site ng iyong mga kliyente','Lists everything you have provisioned for your clients (client_id and status narrow it), a page at a time.'=>'Inililista ang lahat ng na-provision mo para sa iyong mga kliyente (nililimitahan ito ng client_id at status), nang tig-isang pahina bawat pagkakataon.','Create a site for a client'=>'Gumawa ng site para sa isang kliyente','Creates a hosted site for one of your clients (client_id, product_line, primary_domain). It is billed to your account at the client\'s plan, as from your shop.'=>'Lumilikha ng isang hosted site para sa isa sa iyong mga kliyente (client_id, product_line, primary_domain). Sisingilin ito sa iyong account batay sa plano ng kliyente, tulad ng mula sa iyong tindahan.','Suspend a client\'s site'=>'Isuspinde ang site ng kliyente','Puts a client\'s site on a non-payment hold (site_id; reason: your own note, never shown to the client). The site stops serving until it is unsuspended.'=>'Inilalagay ang site ng kliyente sa hold dahil sa hindi pagbabayad (site_id; reason: sarili mong tala, hindi kailanman ipinapakita sa kliyente). Hihinto ang site sa pagseserbisyo hanggang sa maalis ang pagkakasuspinde nito.','Unsuspend a client\'s site'=>'I-unsuspend ang site ng isang kliyente','Lifts a non-payment hold, so the site serves again (site_id).'=>'Tinatanggal ang hold dahil sa hindi pagbabayad, upang muling gumana ang site (site_id).','Read the Reseller Toolkit settings'=>'Basahin ang mga setting ng Reseller Toolkit','Returns this plugin\'s settings (the API address, the plan new orders use, which features are on). The API key is never returned, only whether one is saved.'=>'Ibinabalik ang mga setting ng plugin na ito (ang address ng API, ang planong ginagamit ng mga bagong order, kung aling mga feature ang naka-on). Hindi kailanman ibinabalik ang API key, kundi kung may naka-save lamang.','Change the Reseller Toolkit settings'=>'Baguhin ang mga setting ng Reseller Toolkit','Changes the settings you send (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) and keeps the rest. The API key and address are changed on the screen only.'=>'Binabago ang mga setting na ipapadala mo (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) at pinapanatili ang iba pa. Ang API key at address ay binabago sa screen lamang.','Add your Zinn Digital® reseller API key on the Reseller Toolkit screen first.'=>'Idagdag muna ang iyong Zinn Digital® reseller API key sa screen ng Reseller Toolkit.']];